const SESSION_CUSTOMER = 'KD-1001';
const orders = {
  'KD-1001': [{ id: 'B-5001', artikel: 'Powerbank 20000mAh', status: 'versendet' }],
  'KD-2002': [{ id: 'B-5002', artikel: 'USB-C Ladegeraet', status: 'in Bearbeitung' }]
};
const q = (typeof query !== 'undefined' && query) ? String(query) : '';
const m = q.toUpperCase().match(/KD-\d+/);
const requested = m ? m[0] : SESSION_CUSTOMER;
if (requested !== SESSION_CUSTOMER) {
  return JSON.stringify({ fehler: 'ZUGRIFF VERWEIGERT', angefragt: requested, erlaubt: SESSION_CUSTOMER, hinweis: 'Es duerfen nur Bestellungen des eingeloggten Kunden abgerufen werden.' });
}
return JSON.stringify({ kunde: SESSION_CUSTOMER, bestellungen: orders[SESSION_CUSTOMER] });
